<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Models\LifeGroup; use App\Models\LifeGroupMember; use Illuminate\Http\Request;
class LifeGroupController extends Controller { public function index(Request $r){$q=LifeGroup::query()->where('is_active',true)->withCount(['members'=>fn($x)=>$x->where('status','active')]); if($r->filled('organisation_unit_id'))$q->where('organisation_unit_id',$r->integer('organisation_unit_id')); return response()->json($q->paginate(12));} public function join(Request $r,LifeGroup $lifeGroup){$active=$lifeGroup->members()->where('status','active')->count(); if($active >= $lifeGroup->member_limit)return response()->json(['message'=>'This Life Group has reached its member limit.'],422); $member=LifeGroupMember::updateOrCreate(['life_group_id'=>$lifeGroup->id,'user_id'=>$r->user()->id],['role'=>'member','status'=>'active']); return response()->json(['message'=>'You have joined the Life Group.','data'=>$member]);} }
